query catalogThemes($categoryCode: String!, $sortVariantCode: String, $search: String, $isEducont: Boolean) {
  catalogThemes(
    categoryCode: $categoryCode
    sortVariantCode: $sortVariantCode
    search: $search
    isEducont: $isEducont
  ) {
    id
    name
    number
    code
    classId
    classDigit
    subjectId
    subThemesTotal
    subThemesSolved
    subThemes {
      id
      name
      number
      code
    }
    sortVariatns {
      code
    }
    stat {
      resolveTasks
    }
    isSchoolProgram
  }
}
